    throw Object.assign(new Error('gateway authentication required'), { status: 401 });
  }
  const identity = JSON.parse(headers['x-relay-identity'] || '{}');
  if (typeof identity.subject !== 'string' || !Array.isArray(identity.projects)) throw new Error('invalid identity');
  if (!identity.projects.every(value => typeof value === 'string')) throw new Error('invalid project claims');
  return Object.freeze({ subject: identity.subject, projects: Object.freeze([...identity.projects]) });
}

export function authorizeProject(actor, project) {
  if (!actor.projects.includes(project)) {
    throw Object.assign(new Error('project denied'), { status: 403 });
  }
  return Object.freeze({ subject: actor.subject, project });
}

import http from 'node:http';
import https from 'node:https';
export function retrieve(value) {
  const url = new URL(value);
  if (url.protocol !== 'http:' && url.protocol !== 'https:') throw new Error('unsupported transfer protocol');
  const protocol = url.protocol === 'https:' ? https : http;
  return new Promise((resolve, reject) => {
    const request = protocol.get(url, response => {
      let text = '';
      response.setEncoding('utf8');
      response.on('data', chunk => {
        text += chunk;
        if (Buffer.byteLength(text) > 16384) request.destroy(new Error('source too large'));
      });
      response.on('end', () => resolve({ status: response.statusCode, text }));
      response.on('error', reject);
    });
    request.setTimeout(2000, () => request.destroy(new Error('source timeout')));
    request.on('error', reject);
  });
}

import { makeTransfer } from './transfer.mjs';
import { eventFor } from '../audit.mjs';
export async function collectSource(project, approved, body, configuration, transport) {
  const transfer = makeTransfer(project, approved, body);
  const result = await transport.retrieve(transfer.url);
  return {
    text: result.text,
    event: eventFor('source.collected', project, { host: approved.host }),
    status: result.status
  };
}
